      id: 'chengdu-jinli-street', city: 'chengdu', category: 'attraction', spot: 'insta', lat: 30.6450, lng: 104.0490, image: 'Eg7zkiPNtpU',
      rating: 4.4, reviews: 22100, tags: ['oldtown', 'photo', 'streetfood', 'culture'], price: { kind: 'free' }, hours: 'always',
      address: '231 Wuhouci St, Wuhou, Chengdu',
      text: {
        ru: { name: 'Улица Цзиньли', description: 'Реконструированная старинная улица рядом с храмом Ухоу, посвящённым эпохе Троецарствия: деревянные дома, лавки с чаем и вышивкой, уличные закуски и театр смены масок. Вечером её заливает красный свет сотен фонарей.', tip: 'Приходите после 19:00, когда зажигаются фонари, и снимайте с горбатого мостика над прудом в глубине улицы.' },
        en: { name: 'Jinli Ancient Street', description: 'A reconstructed old street beside the Wuhou Shrine, dedicated to the Three Kingdoms era: wooden houses, tea and embroidery shops, street snacks and face-changing opera. In the evening it glows red under hundreds of lanterns.', tip: 'Come after 7 p.m., once the lanterns are lit, and shoot from the humpback bridge over the pond at the far end of the street.' },
        es: { name: 'Calle antigua de Jinli', description: 'Una calle antigua reconstruida junto al templo Wuhou, dedicado a la época de los Tres Reinos: casas de madera, tiendas de té y bordados, tentempiés callejeros y ópera de cambio de máscaras. Al anochecer la tiñen de rojo cientos de farolillos.', tip: 'Ven después de las 19:00, cuando se encienden los farolillos, y haz la foto desde el puente arqueado sobre el estanque, al fondo de la calle.' },
        de: { name: 'Jinli-Altstadtgasse', description: 'Eine rekonstruierte alte Gasse neben dem Wuhou-Schrein, der der Zeit der Drei Reiche gewidmet ist: Holzhäuser, Tee- und Stickereiläden, Straßensnacks und Maskenwechsel-Oper. Abends leuchtet sie rot unter Hunderten Laternen.', tip: 'Komm nach 19 Uhr, wenn die Laternen brennen, und fotografiere von der Buckelbrücke über dem Teich am hinteren Ende der Gasse.' },
        fr: { name: 'Rue ancienne de Jinli', description: 'Une vieille rue reconstituée près du temple Wuhou, dédié à l’époque des Trois Royaumes : maisons de bois, boutiques de thé et de broderie, en-cas de rue et opéra des masques changeants. Le soir, des centaines de lanternes la baignent de rouge.', tip: 'Venez après 19 heures, une fois les lanternes allumées, et photographiez depuis le pont en dos d’âne au-dessus de l’étang, au fond de la rue.' },
        it: { name: 'Antica via Jinli', description: 'Una vecchia via ricostruita accanto al tempio Wuhou, dedicato all’epoca dei Tre Regni: case di legno, botteghe di tè e ricami, snack di strada e l’opera del cambio delle maschere. La sera si tinge di rosso sotto centinaia di lanterne.', tip: 'Vieni dopo le 19, quando si accendono le lanterne, e scatta dal ponte a schiena d’asino sullo stagno in fondo alla via.' },
      },
